{"Channel": {"name": "bug-davidgarcia-ForecastForce", "channelID": "ch-force-d1c875"}, "Message": {"User": {"userId": "eid_bd791efc", "timestamp": "2026-09-24T14:00:00", "text": "Awesome, thanks everyone! If you need any more details or run into issues, feel free to reach out. Let's get these resolved for our customers! 💪", "utterranceID": "20260924-7-abe16"}, "Reactions": []}, "ThreadReplies": [], "id": "20260924-7-abe16"}
{"Channel": {"name": "bug-davidgarcia-ForecastForce", "channelID": "ch-force-d1c875"}, "Message": {"User": {"userId": "eid_8333ab24", "timestamp": "2026-09-24T14:03:00", "text": "Will do! Thanks for the heads-up. 😊", "utterranceID": "20260924-8-2ed74"}, "Reactions": []}, "ThreadReplies": [], "id": "20260924-8-2ed74"}
