{"Channel": {"name": "bug-bobmiller-MonitorForce", "channelID": "ch-force-c6eeee"}, "Message": {"User": {"userId": "eid_9de52b6e", "timestamp": "2026-09-19T04:28:00", "text": "Awesome work, Hannah! It's reassuring to know that we have better checks in place now.", "utterranceID": "20260919-5-3ac32"}, "Reactions": []}, "ThreadReplies": [], "id": "20260919-5-3ac32"}
